/// Next scanline: update VCOUNT, the VBlank flag (lines 160-226) and the VCount match.
fn start_next_line(&mut self, irq: &mut Irq, events: &mut PpuEvents) {
    self.dispstat &= !DISPSTAT_HBLANK_FLAG;
